-- Generated by scripts/build-sql.mjs. Local Frontier server only.
-- Frontier Wars local authority. Separate from existing Supabase campaign tables.
-- Run only through the local server; no browser/database credentials are exposed.
create schema if not exists frontier;
create sequence if not exists frontier.ids;
create table if not exists frontier.realm (
    singleton boolean primary key default true check (singleton),
    config jsonb not null,
    village_sites jsonb not null,
    created_at double precision not null
);
create table if not exists frontier.villages (
    id text primary key,
    col integer not null check (col between -100 and 99),
    row integer not null check (row between -100 and 99),
    data jsonb not null,
    unique (col, row)
);
create table if not exists frontier.sessions (
    token_hash text primary key,
    owner_id text not null references frontier.villages(id)
);
create table if not exists frontier.camps (
    id text primary key,
    col integer not null check (col between -100 and 99),
    row integer not null check (row between -100 and 99),
    at double precision,
    data jsonb not null,
    unique (col, row)
);
create index if not exists camps_due on frontier.camps (at, id) where at is not null;
alter table frontier.camps alter column at drop not null;
create table if not exists frontier.training (
    id text primary key,
    owner_id text not null references frontier.villages(id),
    at double precision not null,
    data jsonb not null
);
create index if not exists training_due on frontier.training (at, id);
create index if not exists training_owner on frontier.training (owner_id);
create table if not exists frontier.research (
    id text primary key,
    owner_id text not null references frontier.villages(id),
    unit text not null,
    at double precision not null,
    data jsonb not null,
    unique (owner_id, unit)
);
create index if not exists research_due on frontier.research (at, id);
create table if not exists frontier.raids (
    id text primary key,
    owner_id text not null references frontier.villages(id),
    camp_id text not null references frontier.camps(id),
    status text not null check (status in ('outbound', 'returning', 'complete')),
    at double precision,
    data jsonb not null,
    check ((status = 'complete') = (at is null))
);
create index if not exists raids_due on frontier.raids (at, id) where at is not null;
create index if not exists raids_owner on frontier.raids (owner_id, status);
create table if not exists frontier.farms (
    id text primary key,
    owner_id text not null references frontier.villages(id),
    camp_id text not null references frontier.camps(id),
    at double precision,
    data jsonb not null,
    unique (owner_id, camp_id)
);
create index if not exists farms_due on frontier.farms (at, id) where at is not null;
create index if not exists farms_owner on frontier.farms (owner_id);
create table if not exists frontier.farm_lists (
    id text primary key,
    owner_id text not null references frontier.villages(id),
    data jsonb not null
);
create index if not exists farm_lists_owner on frontier.farm_lists (owner_id);
-- Existing targets, schedules and troops stay intact when upgrading a saved realm.
insert into frontier.farm_lists(id,owner_id,data)
select distinct 'legacy-' || owner_id, owner_id,
    jsonb_build_object('id','legacy-' || owner_id,'ownerId',owner_id,'name','Saved farms','casualtiesOnly',false)
from frontier.farms where not (data ? 'listId')
on conflict (id) do nothing;
update frontier.farms set data=jsonb_set(data,'{listId}',to_jsonb('legacy-' || owner_id))
where not (data ? 'listId');
-- A list preset never rewrites existing per-target troop selections.
update frontier.farm_lists set data=jsonb_set(data,'{troops}','{"infantry":1,"archers":0,"cavalry":0}'::jsonb)
where not (data ? 'troops');
create table if not exists frontier.commands (
    owner_id text not null references frontier.villages(id),
    request_id text not null,
    command jsonb not null,
    primary key (owner_id, request_id)
);
